package com.sky.controller.admin;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

import java.util.Collections;
import java.util.Set;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.data.redis.core.RedisTemplate;

import com.sky.result.Result;
import com.sky.service.DishService;

@ExtendWith(MockitoExtension.class)
class DishControllerTest {

    @InjectMocks
    private DishController dishController;

    @Mock
    private DishService dishService;

    @Mock
    private RedisTemplate<String, Object> redisTemplate;

    @Test
    @DisplayName("正向测试：修复后，当status为1且id正常时，方法能正确工作并返回成功")
    void testStartOrStop_NormalInput_ShouldReturnSuccess() {
        // Arrange
        Integer status = 1;
        Long id = 1L;
        Set<String> cacheKeys = Collections.singleton("dish_*");
        when(redisTemplate.keys("dish_*")).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);

        // Act
        Result<String> result = dishController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.getCode());
        verify(dishService).startOrStop(eq(status), eq(id));
        verify(redisTemplate).keys("dish_*");
        verify(redisTemplate).delete(any(Set.class));
    }

    @Test
    @DisplayName("边界测试：修复后，当status为0（停用）时，方法能正常处理而不抛出异常")
    void testStartOrStop_StatusZero_ShouldNotThrowException() {
        // Arrange
        Integer status = 0;
        Long id = 2L;
        Set<String> cacheKeys = Collections.singleton("dish_*");
        when(redisTemplate.keys("dish_*")).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);

        // Act & Assert
        assertDoesNotThrow(() -> {
            Result<String> result = dishController.startOrStop(status, id);
            assertNotNull(result);
            assertEquals(1, result.getCode());
        });

        verify(dishService).startOrStop(eq(status), eq(id));
    }

    @Test
    @DisplayName("null处理测试：当id为null时，方法能正常处理而不抛出NullPointerException")
    void testStartOrStop_NullId_ShouldNotThrowNPE() {
        // Arrange
        Integer status = 1;
        Long id = null;
        Set<String> cacheKeys = Collections.singleton("dish_*");
        when(redisTemplate.keys("dish_*")).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);

        // Act & Assert
        assertDoesNotThrow(() -> {
            Result<String> result = dishController.startOrStop(status, id);
            assertNotNull(result);
            assertEquals(1, result.getCode());
        });

        verify(dishService).startOrStop(eq(status), eq(id));
    }

    @Test
    @DisplayName("null处理测试：当status为null时，方法能正常处理而不抛出NullPointerException")
    void testStartOrStop_NullStatus_ShouldNotThrowNPE() {
        // Arrange
        Integer status = null;
        Long id = 1L;
        Set<String> cacheKeys = Collections.singleton("dish_*");
        when(redisTemplate.keys("dish_*")).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);

        // Act & Assert
        assertDoesNotThrow(() -> {
            Result<String> result = dishController.startOrStop(status, id);
            assertNotNull(result);
            assertEquals(1, result.getCode());
        });

        verify(dishService).startOrStop(eq(status), eq(id));
    }
}
